first = boundary retry 2 {
    return list_orders({ month: "2026-03", page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_orders({ month: "2026-03", page: page }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
listing = fold acc = first.items for page in remaining { return acc + page }

enriched = for order in listing {
    detail = get_order({ id: order.id })
    skip if detail.status != "completed"
    customer = get_customer({ id: order.customer_id })
    return {
        region: customer.region,
        amount: detail.amount_cents
    }
}

totals = fold acc = { NA: 0, EU: 0, APAC: 0 } for row in enriched {
    return acc + { [row.region]: acc[row.region] + row.amount }
}

submitted = submit_result({ answer: totals })
return { totals, submitted }

